 import pandas as pd
import numpy as np
import re
import os

input_path = r"C:/Users/darpa/Downloads/Resume_Projects/AI Data Agent/data/etl_eval/input/payments_messy.csv"
output_dir = r"C:/Users/darpa/Downloads/Resume_Projects/AI Data Agent/data/etl_eval/output/h06"
os.makedirs(output_dir, exist_ok=True)

df = pd.read_csv(input_path)

def clean_amount(val):
    if pd.isna(val):
        return np.nan
    s = str(val)
    s = re.sub(r'[^0-9.\-]', '', s)
    if s == '' or s == '-':
        return np.nan
    try:
        return float(s)
    except ValueError:
        return np.nan

df['amount_cad'] = df['amount'].apply(clean_amount)

def clean_date(val):
    if pd.isna(val):
        return None
    s = str(val).strip()
    if '/' in s:
        dt = pd.to_datetime(s, format='%m/%d/%Y', errors='coerce')
    else:
        dt = pd.to_datetime(s, errors='coerce')
    if pd.isna(dt):
        return None
    return dt.strftime('%Y-%m-%d')

df['paid_on'] = df['paid_on'].apply(clean_date)

df = df.drop(columns=['amount'])

output_file = os.path.join(output_dir, "payments_cleaned.parquet")
df.to_parquet(output_file, index=False) 

